entries[244790] = { ["name"] = "The Coiled Huntress", ["text"] = "Binds when picked up\nFishing Tool + 55 Perception\nEquip: +18 Midnight Fishing\n\nEquip: Become a snake when underwater in Midnight Zones, allowing you to breathe water and swim rapidly.\n\nEquip: Successful fishing attempts in the waters of The Coiled Isle will siphon Venom into The Coiled Huntress.\n\n+ Venom\n\nShed Skin\n\nSpeak to Seasage Polo to invoke a ritual and turn your Venom into Coiled Filament. This also alters the rod's appearance, if able.\nRequires Fishing (1)\nRequires Bloodsworn Crew or above with Captain Tokka's Crew." }
entries[244791] = { ["name"] = "Recipe: Amani Angler's Ward", ["text"] = "Binds when picked up\nUse: Teaches you how to craft an Amani Angler's Ward.\nA powerful totem that prevents the spirit of Blood Hunters from taking revenge on Anglers who reel it in.\nRequires Midnight Fishing (1)\n\nAmani Angler's Ward\nUse: Wards any Blood Hunter from attacking for 30 min.\nSell Price:\nRequires Blood Hunter (2)" }
