entries[245694] = { ["name"] = "Reins of the Ivory Savagemane", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Ivory Savagemane.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"According to Raptari legend, during Dazar's first ascent up the slopes of Zandalar, the soon-to-be-King was guided through the darkness by the shimmer of ivory scales and gleaming red eyes.\"\nVendor:\nChurbro\nZone:\nBoralus Harbor\nCost:\n5000\n\nVendor:\nChurbro\nZone:\nZuldazar\nCost:\n5000" }
entries[245695] = { ["name"] = "Reins of the Moonlit Nightsaber", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Moonlit Nightsaber.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Her white glow upon their silvered fur, her bright-blue gaze in their moonlit eyes. Oh, how the moons smile on these creatures.\" -Mother Kalo'thera, High Priestess of Elune, A Blessing in Hajiri\nVendor:\nChurbro\nZone:\nBoralus Harbor\nCost:\n5000\n\nVendor:\nChurbro\nZone:\nZuldazar\nCost:\n5000" }
